280: impl<'a> fmt::Display for DemangleStyle<'a> {
281:     fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
282:         match *self {
283:             DemangleStyle::Legacy(ref d) => fmt::Display::fmt(d, f),
284:             DemangleStyle::V0(ref d) => fmt::Display::fmt(d, f),
285:         }
286:     }
